using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class GroundSurfaceDetailReview{static GroundSurfaceDetailReview(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("GroundSurfaceDetailReview.request"))return;File.Delete("GroundSurfaceDetailReview.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/GroundSurfaceDetail.txt",e.ToString());Debug.LogException(e);}}static void Run(){var sc=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var roots=sc.GetRootGameObjects();var map=roots.Single(g=>g.name=="Track Roads").GetComponent<CityGroundTextureLayout>();if(ShaderUtil.ShaderHasError(map.plots[0].renderer.sharedMaterial.shader))throw new Exception("Ground shader error");var ctrl=roots.SelectMany(g=>g.GetComponentsInChildren<CityDayNightController>(true)).First();bool night=ctrl.IsNight;var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.NonPublic|BindingFlags.Static);try{ctrl.ApplyDay();map.Apply();cap.Invoke(null,new object[]{sc,new Vector3(-359,31.5f,-511),new Vector3(-367,27.74f,-504),"Ground-Detail-Casino-Close"});cap.Invoke(null,new object[]{sc,new Vector3(-83,30.3f,-337),new Vector3(-90,27.74f,-342),"Ground-Detail-Hospital-Close"});cap.Invoke(null,new object[]{sc,new Vector3(247,31.5f,289),new Vector3(244,27.74f,282),"Ground-Detail-Cafe-Close"});cap.Invoke(null,new object[]{sc,new Vector3(-300,60,-495.96f),new Vector3(-390,36,-495.96f),"Ground-Detail-Casino-Overview"});}finally{if(night)ctrl.ApplyNight();else ctrl.ApplyDay();map.Apply();}EditorSceneManager.SaveScene(sc);File.WriteAllText("FinalEnvironmentRoadReview/GroundSurfaceDetail.txt","SUCCESS close-range grain from existing atlas, subtle mineral mottling, filtered pores, worn inlay finish and shallow shader relief across all updated paving. Existing 40 layouts unchanged. No added texture/material/mesh/UV assets. Additional single shared-atlas stone sample on paving only. Shader errors=False. Close views captured.");File.WriteAllText("CityGroundTextureVerify.request","run");}}